import { GoogleGenAI } from "@google/genai";

/**
 * Simple in-memory cache to prevent redundant calls and handle 429s gracefully
 */
const responseCache: Record<string, string> = {
  priority: "",
  admin: "",
  forecast: "",
  news: ""
};

/**
 * Helper to call Gemini with exponential backoff for transient errors
 */
async function generateWithRetry(model: string, prompt: string, cacheKey: string, fallback: string, retries = 2, delay = 1000, tools?: any[]): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        temperature: 0.7,
        topP: 0.9,
        tools: tools,
      }
    });

    // Accessing the text property directly as per guidelines
    const text = response.text;

    // If googleSearch tool was used, we should ideally handle grounding chunks, 
    // but for simplicity in this helper we focus on the text.
    if (text) {
      responseCache[cacheKey] = text;
      return text;
    }
    return responseCache[cacheKey] || fallback;
  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("429") || errorMessage.includes("quota")) {
      if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
        return generateWithRetry(model, prompt, cacheKey, fallback, retries - 1, delay * 2, tools);
      }
      return responseCache[cacheKey] || fallback;
    }
    console.error(`Gemini API Error (${cacheKey}):`, error);
    return responseCache[cacheKey] || fallback;
  }
}

export const getPriorityInsights = async (history: any[], userName: string) => {
  const prompt = `
    Context: A Medical Representative (MR) named ${userName} is using a hospital pass booking system.
    System Rules:
    - 14 days without a pass: +5 priority points.
    - 7 days without a pass: +3 priority points.
    - Pass in last 3 days: -5 priority points (Cool-down period).
    - Missed entry (no-show): -10 points.

    User Recent History: ${JSON.stringify(history)}

    Task: Write a 2-sentence encouraging insight for ${userName}. 
    Explain their current standing and give one tip to improve their chances in the next lottery.
    Tone: Professional, supportive, and clear.
  `;

  const defaultFallback = "Your priority is calculated based on recent visits to ensure fairness. Regular participation helps maintain a steady rank.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "priority", defaultFallback);
};

export const getAdminBriefing = async (apps: any[], passes: any[], hospitalName: string) => {
  const prompt = `
    Context: You are an AI analyst for ${hospitalName}. 
    Today's Data: 
    - Total Applications: ${apps.length}
    - Passes Issued: ${passes.length}
    - Success Rate: ${apps.length > 0 ? ((passes.length / apps.length) * 100).toFixed(1) : 0}%

    Task: Provide a one-sentence high-level summary of today's demand and a specific recommendation for tomorrow's pass limits to optimize traffic flow.
    Tone: Analytical and concise.
  `;

  const defaultFallback = "Demand is currently stable. Maintain existing pass limits to balance MR access with hospital operations.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "admin", defaultFallback);
};

export const getTrafficForecast = async (history: any[], hospitalName: string) => {
  const prompt = `
    Analyze the historical pass booking data for ${hospitalName}:
    Data: ${JSON.stringify(history)}

    Task: Forecast demand for the upcoming week. Identify potential peak days and suggest if session limits should be increased or decreased.
    Be specific with days (e.g., "Mondays show 20% higher demand").
    Tone: Data-driven and professional.
  `;

  const defaultFallback = "Forecasting data indicates stable demand for the upcoming week. Recommend maintaining current session capacities.";

  return generateWithRetry('gemini-3-pro-preview', prompt, "forecast", defaultFallback);
};

export const getPharmaNews = async () => {
  const prompt = `
    Search for latest pharmaceutical regulations and healthcare news in Sri Lanka for 2024-2025. 
    Summarize the top 2 relevant updates for Medical Representatives.
  `;

  const defaultFallback = "Stay updated with local health authority guidelines and SLCPI regulations to ensure compliant hospital visits.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "news", defaultFallback, 2, 1000, [{ googleSearch: {} }]);
};

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
  CheckCircle, TrendingUp, AlertTriangle, Info, Calendar, Mail, Phone, Eye, EyeOff, MapPin, CreditCard, DollarSign, FileText, Download, Send
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser, PassApplication, IssuedPass, Invoice } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring' | 'billing'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [showPasswords, setShowPasswords] = useState(false);

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setMrs(storageService.getMRs());
    setApps(storageService.getApplications());
    setPasses(storageService.getPasses());
    setInvoices(storageService.getInvoices());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      address: editingHospital.address || '',
      email: editingHospital.email || '',
      mobileNumber: editingHospital.mobileNumber || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    const currentHospitals = storageService.getHospitals();
    const updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === hospitalId ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    storageService.saveHospitals(updatedHospitals);

    // Save Hospital User Accounts
    const u: HospitalUser[] = [
      { id: editingHospital.id ? (storageService.getHospitalUsers().find(user => user.hospitalId === hospitalId && user.role === 'ADMIN')?.id || `u-a-${hospitalId}`) : `u-a-${hospitalId}`, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: editingHospital.id ? (storageService.getHospitalUsers().find(user => user.hospitalId === hospitalId && user.role === 'SECURITY')?.id || `u-s-${hospitalId}`) : `u-s-${hospitalId}`, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ];

    const currentUsers = storageService.getHospitalUsers().filter(user => user.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([...currentUsers, ...u]);

    refreshData();
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
    showFeedback(editingHospital.id ? "Hospital infrastructure updated." : "New facility provisioned.");
  };

  const startEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers().filter(u => u.hospitalId === h.id);
    const admin = users.find(u => u.role === 'ADMIN');
    const security = users.find(u => u.role === 'SECURITY');

    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
      password: security?.password || '' 
    });
    setIsHospitalModalOpen(true);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) {
      showFeedback("Company name and code are required.", "error");
      return;
    }

    const companyId = editingCompany.id || 'c' + Date.now();
    const companyData: PharmaCompany = {
      id: companyId,
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      address: editingCompany.address || '',
      contactNumber: editingCompany.contactNumber || '',
      financeEmail: editingCompany.financeEmail || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    const currentCompanies = storageService.getCompanies();
    const updated = editingCompany.id 
      ? currentCompanies.map(c => c.id === companyId ? companyData : c)
      : [...currentCompanies, companyData];

    storageService.saveCompanies(updated);
    refreshData();
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
    showFeedback(`Pharmaceutical company ${companyData.name} registered.`);
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    const c = updated.find(x => x.id === id);
    showFeedback(`Company ${c?.name} is now ${c?.isActive ? 'active' : 'deactivated'}`);
  };

  const handleGenerateInvoices = () => {
    const BASE_FEE_PER_MR = 1000; // Example LKR
    const today = new Date().toISOString().split('T')[0];

    const newInvoices: Invoice[] = companies.filter(c => c.isActive).map(c => {
      const activeMRCount = mrs.filter(m => m.companyName === c.name && m.status === 'active').length;
      return {
        id: `INV-${Date.now()}-${c.id.slice(0, 4)}`,
        companyId: c.id,
        amount: activeMRCount * BASE_FEE_PER_MR,
        activeMRCount,
        status: 'unpaid',
        date: today
      };
    });

    if (newInvoices.length === 0) {
      showFeedback("No active companies to invoice.", "error");
      return;
    }

    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    showFeedback(`Generated ${newInvoices.length} monthly invoices.`);
  };

  const totalOutstanding = invoices.filter(i => i.status === 'unpaid').reduce((sum, i) => sum + i.amount, 0);

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
      </div>

      {/* Hospitals Management */}
      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Facility Management</h3>
            <button 
              onClick={() => { 
                setEditingHospital({ supportedSessions: ['MORNING', 'EVENING', 'FULL_DAY'], isActive: true }); 
                setAdminData({ fullName: '', mobileNumber: '', password: '' });
                setSecurityData({ fullName: '', mobileNumber: '', password: '' });
                setIsHospitalModalOpen(true); 
              }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> PROVISION HOSPITAL
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 relative group hover:shadow-md transition-all">
                <div className={`absolute top-4 right-4 w-2 h-2 rounded-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <h4 className="font-black text-slate-800 text-lg mb-1">{h.name}</h4>
                <p className="text-[10px] text-slate-400 font-bold flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Address not set'}</p>
                <div className="space-y-2 mb-6">
                   <div className="flex items-center gap-2 text-xs font-bold text-slate-500">
