import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  UserPlus, Search, Briefcase, Mail, Phone, CreditCard, X, Edit3, Trash2, Power, 
  User, ShieldCheck, Activity, Users, Plus, Key, BarChart3, Clock, CheckCircle2, 
  Image as ImageIcon, Upload, Calendar, MapPin, DollarSign, Save, Copy, Check, AlertCircle, ArrowRight, FileText, CheckCircle
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser, PassApplication, IssuedPass, Invoice } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [allApps, setAllApps] = useState<PassApplication[]>([]);
  const [allPasses, setAllPasses] = useState<IssuedPass[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [activeTab, setActiveTab] = useState<'staff' | 'profile' | 'invoices'>('staff');
  const [searchTerm, setSearchTerm] = useState('');
  const [isMRModalOpen, setIsMRModalOpen] = useState(false);
  const [editingMR, setEditingMR] = useState<Partial<MedicalRep> | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSavedMR, setLastSavedMR] = useState<MedicalRep | null>(null);

  const [summaryMR, setSummaryMR] = useState<MedicalRep | null>(null);
  const [editingProfile, setEditingProfile] = useState<PharmaCompany | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    const allCompanies = storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      setEditingProfile(myCompany);
      const allMRs = storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
      const allInvoices = storageService.getInvoices();
      setInvoices(allInvoices.filter(i => i.companyId === myCompany.id));
    }
    setAllApps(storageService.getApplications());
    setAllPasses(storageService.getPasses());
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
    showFeedback("Copied to clipboard");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMR(prev => ({ ...prev, slcpiPhoto: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMR = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMR?.fullName || !editingMR?.mobileNumber || !editingMR?.loginId || !company) {
      showFeedback("Required fields missing.", "error");
      return;
    }

    setIsSaving(true);

    const allMRs = storageService.getMRs();
    const duplicate = allMRs.find(m => m.loginId === editingMR.loginId && m.id !== editingMR.id);
    if (duplicate) {
      showFeedback("Login ID is already taken in the system.", "error");
      setIsSaving(false);
      return;
    }

    const mrData: MedicalRep = {
      id: editingMR.id || 'mr-' + Date.now(),
      fullName: editingMR.fullName,
      companyName: company.name,
      mrId: editingMR.mrId || `SLCPI-${Math.floor(10000 + Math.random() * 90000)}`,
      loginId: editingMR.loginId,
      mobileNumber: editingMR.mobileNumber,
      password: editingMR.password || 'mr123', 
      identificationNumber: editingMR.identificationNumber || '',
      slcpiId: editingMR.slcpiId || '',
      slcpiPhoto: editingMR.slcpiPhoto,
      slcpiExpiry: editingMR.slcpiExpiry,
      status: (editingMR.status as any) || 'active',
      createdAt: editingMR.createdAt || new Date().toISOString()
    };

    let updated: MedicalRep[];
    if (editingMR.id) {
      updated = allMRs.map(m => m.id === editingMR.id ? mrData : m);
      storageService.saveMRs(updated);
      setMrs(updated.filter(m => m.companyName === company.name));
      setIsMRModalOpen(false);
      setEditingMR(null);
      setIsSaving(false);
      showFeedback(`Updated profile for ${mrData.fullName}`);
    } else {
      updated = [...allMRs, mrData];
      storageService.saveMRs(updated);
      setMrs(updated.filter(m => m.companyName === company.name));
      setLastSavedMR(mrData);
      setIsSaving(false);
      showFeedback(`Successfully registered ${mrData.fullName}`, 'success');
    }
  };

  const handlePayInvoice = (invoiceId: string) => {
    const allInvoices = storageService.getInvoices();
    const updated = allInvoices.map(i => i.id === invoiceId ? { ...i, status: 'paid' as const } : i);
    storageService.saveInvoices(updated);
    setInvoices(updated.filter(i => i.companyId === user.companyId));
    showFeedback("Payment successful!", "success");
  };

  const closeModal = () => {
    setLastSavedMR(null);
    setIsMRModalOpen(false);
    setEditingMR(null);
  };

  const handleSaveProfile = () => {
    if (!editingProfile) return;
    const allCompanies = storageService.getCompanies();
    const updated = allCompanies.map(c => c.id === editingProfile.id ? editingProfile : c);
    storageService.saveCompanies(updated);
    setCompany(editingProfile);
    showFeedback("Company profile updated successfully.");
  };

  const toggleMRStatus = (id: string) => {
    const allMRs = storageService.getMRs();
    const target = allMRs.find(m => m.id === id);
    const newStatus = target?.status === 'active' ? 'suspended' : 'active';
    const updated = allMRs.map(m => m.id === id ? { ...m, status: newStatus as any } : m);
    storageService.saveMRs(updated);
