import { createClient } from '@supabase/supabase-js';
import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, Invoice, HospitalUser, AuthUser } from '../types';

const supabaseUrl = process.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = process.env.VITE_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const KEYS = {
  SESSION: 'medpass_session',
};

export const storageService = {
  // Medical Representatives
  getMRs: async (): Promise<MedicalRep[]> => {
    const { data, error } = await supabase.from('mrs').select('*');
    if (error) throw error;
    return data || [];
  },
  saveMRs: async (mrs: MedicalRep[]) => {
    // For upserting multiple records
    const { error } = await supabase.from('mrs').upsert(mrs);
    if (error) throw error;
  },

  // Hospitals
  getHospitals: async (): Promise<Hospital[]> => {
    const { data, error } = await supabase.from('hospitals').select('*');
    if (error) throw error;
    return data || [];
  },
  saveHospitals: async (hospitals: Hospital[]) => {
    const { error } = await supabase.from('hospitals').upsert(hospitals);
    if (error) throw error;
  },

  // Hospital Users (Admins/Security)
  getHospitalUsers: async (): Promise<HospitalUser[]> => {
    const { data, error } = await supabase.from('hospital_users').select('*');
    if (error) throw error;
    return data || [];
  },
  saveHospitalUsers: async (users: HospitalUser[]) => {
    const { error } = await supabase.from('hospital_users').upsert(users);
    if (error) throw error;
  },

  // Approvals
  getApprovals: async (): Promise<MRHospitalApproval[]> => {
