{
  "name": "medpass-backend",
  "version": "1.0.0",
  "description": "Secure API for MedPass Hospital System",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "@google/genai": "^1.40.0",
    "@supabase/supabase-js": "^2.45.4",
    "cors": "^2.8.5",
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "helmet": "^7.1.0",
    "morgan": "^1.10.0"
  },
  "devDependencies": {
    "nodemon": "^3.1.0"
  }
}

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
require('dotenv').config();
const { GoogleGenAI } = require('@google/genai');
const { createClient } = require('@supabase/supabase-js');

const app = express();
const PORT = process.env.PORT || 3001;

// Supabase Setup
const supabaseUrl = process.env.VITE_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY; // Use Service Role for backend operations
const supabase = createClient(supabaseUrl, supabaseKey);

// Gemini Setup
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Middleware
app.use(helmet());
app.use(cors());
app.use(express.json({ limit: '10mb' }));
app.use(morgan('combined'));

// --- Authentication Middleware ---
const authenticate = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing token' });

  const token = authHeader.split(' ')[1];
  const { data: { user }, error } = await supabase.auth.getUser(token);

  if (error || !user) return res.status(401).json({ error: 'Invalid session' });

  // Attach profile and role info to request
  const { data: profile } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single();

  req.user = { ...user, profile };
  next();
};

// --- RBAC Middleware ---
const authorize = (roles = []) => {
  return (req, res, next) => {
    if (!req.user || !req.user.profile) return res.status(401).json({ error: 'Not authenticated' });
    if (roles.length && !roles.includes(req.user.profile.role)) {
      return res.status(403).json({ error: 'Access denied: insufficient permissions' });
    }
    next();
  };
};

// --- Routes ---

// 1. AI: Priority Insights
app.post('/api/ai/priority-insights', authenticate, async (req, res) => {
  const { history, userName } = req.body;
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Context: A Medical Representative (MR) named ${userName} is using a hospital pass booking system.
    System Rules:
    - 14 days without a pass: +5 priority points.
    - 7 days without a pass: +3 priority points.
    - Pass in last 3 days: -5 priority points (Cool-down period).
    - Missed entry (no-show): -10 points.

    User Recent History: ${JSON.stringify(history)}

    Task: Write a 2-sentence encouraging insight for ${userName}. 
    Explain their current standing and give one tip to improve their chances in the next lottery.
    Tone: Professional, supportive, and clear.
  `;

  try {
    const response = await ai.models.generateContent({ model, contents: prompt });
    res.json({ insight: response.text });
  } catch (error) {
    res.status(500).json({ error: 'AI generation failed' });
  }
});

// 2. AI: Admin Briefing
app.post('/api/ai/admin-briefing', authenticate, authorize(['ADMIN', 'SUPER_ADMIN']), async (req, res) => {
  const { apps, passes, hospitalName } = req.body;
  const model = 'gemini-3-flash-preview';

  const prompt = `
    Context: You are an AI analyst for ${hospitalName}. 
    Today's Data: 
    - Total Applications: ${apps.length}
    - Passes Issued: ${passes.length}
    - Success Rate: ${apps.length > 0 ? ((passes.length / apps.length) * 100).toFixed(1) : 0}%

    Task: Provide a one-sentence high-level summary of today's demand and a specific recommendation for tomorrow's pass limits to optimize traffic flow.
    Tone: Analytical and concise.
  `;

  try {
    const response = await ai.models.generateContent({ model, contents: prompt });
    res.json({ briefing: response.text });
  } catch (error) {
    res.status(500).json({ error: 'Briefing generation failed' });
  }
});

// 3. Lottery Execution (Moved to Backend)
app.post('/api/lottery/run', authenticate, authorize(['ADMIN', 'SUPER_ADMIN']), async (req, res) => {
  const { hospitalId, session } = req.body;

  try {
    // 1. Fetch Hospital Settings
    const { data: hospital } = await supabase.from('hospitals').select('*').eq('id', hospitalId).single();
    if (!hospital) return res.status(404).json({ error: 'Hospital not found' });

    const today = new Date().toISOString().split('T')[0];

    // 2. Check if already run
    const { data: existingPasses } = await supabase
      .from('passes')
      .select('id')
      .eq('hospital_id', hospitalId)
      .eq('session', session)
      .eq('pass_date', today);

    if (existingPasses && existingPasses.length > 0) {
      return res.status(400).json({ error: 'Lottery already run for this session today' });
    }

    // 3. Get Scored Applications
    const { data: apps } = await supabase
      .from('applications')
      .select('*')
      .eq('hospital_id', hospitalId)
      .eq('session', session)
      .eq('application_date', today)
      .eq('status', 'applied');

    if (!apps || apps.length === 0) return res.json({ success: true, count: 0, message: 'No applications found' });

    // Scoring logic (simplified for demonstration)
    const scored = apps.sort((a, b) => b.priority_score - a.priority_score);
    const limit = hospital.pass_limits[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    // 4. Update Database (Batch updates)
    const passPayload = selected.map(s => ({
      mr_id: s.mr_id,
      hospital_id: hospitalId,
      session: session,
      pass_date: today,
      entry_status: 'not_entered'
    }));

    await supabase.from('passes').insert(passPayload);

    for (const s of selected) {
      await supabase.from('applications').update({ status: 'selected' }).eq('id', s.id);
    }
    for (const w of waitlisted) {
      await supabase.from('applications').update({ status: 'waitlisted' }).eq('id', w.id);
    }

    res.json({ success: true, count: selected.length });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Lottery execution failed' });
  }
});

// Health Check
app.get('/api/health', (req, res) => res.json({ status: 'operational', timestamp: new Date() }));

app.listen(PORT, () => {
  console.log(`MedPass Backend running on port ${PORT}`);
});

import { storageService } from './storageService';

const API_BASE_URL = process.env.API_BASE_URL || 'http://localhost:3001/api';

export const apiClient = {
  async fetch(endpoint: string, options: RequestInit = {}) {
    const session = storageService.getCurrentUser();
    // In a real implementation, we'd get the actual JWT from Supabase session
    // For this prototype, we'll assume the session contains a token property if it were implemented
    const token = (session as any)?.token || 'demo-token';

    const headers = {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      ...options.headers,
    };

    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      headers,
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'API Request failed');
    }

    return response.json();
  },

  post(endpoint: string, data: any) {
    return this.fetch(endpoint, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }
};

