const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  switch (session) {
    case 'MORNING':
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Morning Window Open', range: '08:00 - 11:45' };
      return { open: false, message: 'Closed: Morning Scan (08:00 - 11:45)', range: '08:00 - 11:45' };
    case 'EVENING':
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Evening Window Open', range: '13:00 - 20:00' };
      return { open: false, message: 'Closed: Evening Scan (13:00 - 20:00)', range: '13:00 - 20:00' };
    case 'FULL_DAY':
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Full Day Window Open', range: '08:00 - 22:30' };
      return { open: false, message: 'Closed: Full Day Scan (08:00 - 22:30)', range: '08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed', range: '--:--' };
  }
};

const getExpiryTimeLabel = (session: SessionType) => {
  if (session === 'MORNING') return '01:00 PM';
  return '08:00 PM';
};

const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => { videoRef.current?.play().catch(console.error); }, 150);
        }
      } catch (err) {
        setError("Camera access denied. Please allow permissions.");
      }
    }
    setupCamera();
    return () => { if (activeStream) activeStream.getTracks().forEach(track => track.stop()); };
  }, []);

  const handleSimulateAuto = async () => {
    const currentPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => p.mr_id === mrId && p.pass_date === today && p.entry_status === 'not_entered');
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);
    if (validPass) {
      onScan(`MEDPASS-GATE-${validPass.hospital_id}`);
    } else {
      onScan(""); 
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"><X className="h-6 w-6" /></button>
        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center"><AlertCircle className="h-12 w-12 text-red-500 mb-4" /><p className="text-white font-bold">{error}</p></div>
          ) : (
            <>
              <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>
        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center"><Smartphone className="h-6 w-6 text-indigo-400" /><h3 className="text-xl font-black text-white">Align with Gate QR</h3></div>
          <button onClick={handleSimulateAuto} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl active:scale-95">SIMULATE GATE DETECTION <Zap className="h-4 w-4" /></button>
        </div>
      </div>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = await storageService.getHospitals();
    const apprvs = await storageService.getApprovals();
    const allApps = await storageService.getApplications();
    const a = allApps.filter(ap => ap.mr_id === user.id);
    const allPasses = await storageService.getPasses();
    const p = allPasses.filter(ps => ps.mr_id === user.id);

    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.application_date, status: app.status })), user.full_name);
    setAiInsight(insight);
  };

  const handleScanDetected = async (qrValueInput?: string) => {
    const latestPasses = await storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    let qrValue = qrValueInput || prompt("Enter Unique Hospital Gate ID (e.g. MEDPASS-GATE-h1):");

    if (!qrValue?.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR format.", "error");
      return;
    }

    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const myPassesToday = latestPasses.filter(p => p.mr_id === user.id && p.pass_date === today && p.entry_status === 'not_entered');
    const myEligiblePasses = myPassesToday.filter(p => p.hospital_id === hospitalIdFromQR);

    if (myEligiblePasses.length === 0) {
      showFeedback("No valid entry pass found for today at this hospital.", "error");
      return;
    }

    const activePass = myEligiblePasses.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      const status = getScanStatus(myEligiblePasses[0].session);
      showFeedback(`Scan Failed: ${status.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entry_status: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      pass_id: activePass.id, 
      entry_time: new Date().toISOString(), 
      verified_by: 'Self-Gate-Scanner' 
    };

    await storageService.savePasses(updatedPasses);
    const currentLogs = await storageService.getLogs();
    await storageService.saveLogs([...currentLogs, log as any]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    await refreshData();
    showFeedback(`Access approved for ${activePass.session} session!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.session_windows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    setLoading(true);
    const todayStr = new Date().toLocaleDateString('en-CA');
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9), mr_id: user.id, hospital_id: hospitalId, session,
      application_date: todayStr, priority_score: 0, status: 'applied', created_at: new Date().toISOString()
    };
    const currentApps = await storageService.getApplications();
    await storageService.saveApplications([...currentApps, newApp]);
    setTimeout(async () => { await refreshData(); setLoading(false); showFeedback("Application submitted!"); }, 600);
  };

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entry_status === 'not_entered' && p.pass_date === todayStr);
  const currentlyVisiting = passes.filter(p => p.entry_status === 'entered' && p.pass_date === todayStr);

  return (
    <div className="space-y-6">
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><CheckCircle2 className="h-16 w-16 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter uppercase">Gate Open</h2>
            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">{countdown}</div>
            </div>
            <button onClick={() => setValidatedPass(null)} className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase shadow-xl active:scale-95 transition-all">Dismiss</button>
          </div>
        </div>
      )}

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> Profile</button>
      </div>

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-500" /> Authorized Facilities</h3>
            </div>
            <div className="grid gap-6 sm:grid-cols-2">
              {hospitals.filter(h => approvals.some(a => a.mr_id === user.id && a.hospital_id === h.id && a.status === 'approved')).map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-all group">
                  <p className="font-bold text-slate-800 text-lg mb-4 group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  <div className="space-y-3">
                    {h.supported_sessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      return (
                        <div key={sess} className="space-y-1">
                          <button 
                            disabled={!open || loading} 
                            onClick={() => handleApply(h.id, sess)} 
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all ${open ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' : 'bg-slate-200 text-slate-400 grayscale cursor-not-allowed'}`}
                          >
                            <span>{sess}</span>
                            <span>{open ? 'APPLY NOW' : 'CLOSED'}</span>
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="space-y-6">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Active Passes</h3>
                {activePassesToday.some(p => getScanStatus(p.session).open) && (
                  <button onClick={() => setIsScanning(true)} className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-md active:scale-95 animate-bounce"><Camera className="h-3.5 w-3.5" /> Scan Gate QR</button>
                )}
              </div>
              <div className="space-y-4">
                {activePassesToday.map(p => {
                  const status = getScanStatus(p.session);
                  return (
                    <div key={p.id} className={`p-4 border-2 rounded-2xl transition-all ${status.open ? 'bg-indigo-50 border-indigo-100 shadow-sm' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                      </div>
                      <p className="font-bold text-slate-800 text-sm mb-3 leading-tight">{hospitals.find(h => h.id === p.hospital_id)?.name}</p>
                      <div className="bg-white p-3 rounded-xl border border-indigo-100 flex justify-between items-center"><div className="text-xs font-black text-slate-700">{p.time_slot}</div></div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        </div>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg"><UserCircle className="h-12 w-12 text-indigo-600" /></div>
            <h3 className="text-2xl font-black text-slate-800">{user.full_name}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.company_name}</p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official MR ID</label><p className="font-bold text-slate-700 font-mono">{user.mr_code}</p></div>
          </div>
        </section>
      )}

      {isScanning && <QRScannerModal onClose={() => setIsScanning(false)} onScan={handleScanDetected} mrId={user.id} />}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = await storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(await storageService.getMRs()); 
    setCompanies(await storageService.getCompanies());
    const allApps = await storageService.getApplications();
    setApps(allApps); 
    const allPasses = await storageService.getPasses();
    setPasses(allPasses);
    setLogs(await storageService.getLogs());
    setApprovals(await storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital(currentHosp);
    }

    try {
      const summary = await getAdminBriefing(allApps, allPasses, currentHosp?.name || 'Hospital');
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
  }, [refreshData]);

  const handleManualLottery = async (session: SessionType) => {
    const result = await lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      await refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = async () => {
    if (!editingHospital) return;
    const allHospitals = await storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    await storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System settings saved successfully.", "success");
  };

  const handleUpdateApproval = async (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = await storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updated_at: new Date().toISOString() } : a);
    await storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return <div className="p-20 text-center text-slate-400">Loading Facility...</div>;

  const pendingApprovals = approvals.filter(a => a.hospital_id === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => approvals.some(a => a.mr_id === mr.id && a.hospital_id === user.hospitalId && a.status === 'approved'));

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium">{brief || "Analyzing patterns..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>Requests</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
             if (!currentHospital.supported_sessions.includes(sess)) return null;
             const today = new Date().toISOString().split('T')[0];
             const count = apps.filter(a => a.hospital_id === user.hospitalId && a.application_date === today && a.session === sess && a.status === 'applied').length;
             return (
               <div key={sess} className="p-6 bg-white border border-slate-100 rounded-3xl shadow-sm">
                 <h4 className="font-black text-slate-800 mb-4">{sess}</h4>
                 <div className="flex items-center justify-between mb-6">
                    <p className="text-xs text-slate-400">Applications Today: {count}</p>
                 </div>
                 <button 
                   disabled={count === 0}
                   onClick={() => handleManualLottery(sess)}
                   className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl hover:bg-indigo-700 disabled:opacity-50"
                 >
                   MANUAL SPIN NOW
                 </button>
               </div>
             );
          })}
        </div>
      )}
    </div>
  );
};

