             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Total System MRs</p><h3 className="text-3xl font-black text-slate-800">{mrs.length}</h3></div>
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Active Hospitals</p><h3 className="text-3xl font-black text-slate-800">{hospitals.filter(h => h.is_active).length}</h3></div>
