import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
  CheckCircle, TrendingUp, AlertTriangle, Info, Calendar, Mail, Phone, Eye, EyeOff, MapPin, CreditCard
} from 'lucide-react';
import { storageService, supabase } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [showPasswords, setShowPasswords] = useState(false);

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    setHospitals(await storageService.getHospitals());
    setCompanies(await storageService.getCompanies());
    setMrs(await storageService.getMRs());
    setApps(await storageService.getApplications());
    setPasses(await storageService.getPasses());
  };

  const handleSaveHospital = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    // Use crypto.randomUUID() to ensure valid UUID format
    const hospitalId = editingHospital.id || crypto.randomUUID();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      address: editingHospital.address || '',
      email: editingHospital.email || '',
      mobile_number: editingHospital.mobile_number || '',
      is_active: editingHospital.is_active ?? true,
      supported_sessions: editingHospital.supported_sessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      pass_limits: editingHospital.pass_limits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      session_windows: editingHospital.session_windows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    const currentHospitals = await storageService.getHospitals();
    const updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === hospitalId ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    await storageService.saveHospitals(updatedHospitals);

    // Profile IDs must also be valid UUIDs
    const allUsers = await storageService.getHospitalUsers();
    const u: any[] = [
      { 
        id: editingHospital.id ? (allUsers.find(user => user.hospital_id === hospitalId && user.role === 'HOSPITAL_ADMIN')?.id || crypto.randomUUID()) : crypto.randomUUID(), 
        hospital_id: hospitalId, 
        role: 'HOSPITAL_ADMIN', 
        full_name: adminData.fullName, 
        mobile_number: adminData.mobileNumber, 
        password: adminData.password 
      },
      { 
        id: editingHospital.id ? (allUsers.find(user => user.hospital_id === hospitalId && user.role === 'SECURITY')?.id || crypto.randomUUID()) : crypto.randomUUID(), 
        hospital_id: hospitalId, 
        role: 'SECURITY', 
        full_name: securityData.fullName, 
        mobile_number: securityData.mobileNumber, 
        password: securityData.password 
      }
    ];

    const currentUsers = allUsers.filter(user => user.hospital_id !== hospitalId);
    const { error: upsertError } = await supabase.from('profiles').upsert([...currentUsers, ...u]);
    if (upsertError) throw upsertError;

    await refreshData();
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
    showFeedback(editingHospital.id ? "Hospital infrastructure updated." : "New facility provisioned.");
  };

