  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = async (e?: React.FormEvent) => {
    e?.preventDefault();
    setIsAuthenticating(true);

    try {
      if (role === 'MR') {
        const mrs = await storageService.getMRs();
        const existing = mrs.find(m => m.login_id === mobile || m.full_name === mobile);
        if (existing) {
          if (existing.status === 'suspended') {
            showFeedback("Account suspended.", 'error');
          } else if (existing.password === password) {
            const u: AuthUser = { 
              id: existing.id, 
              fullName: existing.full_name, 
