        } else {
          showFeedback("Access Denied: Invalid credentials.", 'error');
        }
      }
    } catch (err: any) {
      console.error("Auth Failure:", err);
      showFeedback(err.message || "Connection to secure vault failed.", "error");
    } finally {
      setIsAuthenticating(false);
    }
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
