import { Hospital, PharmaCompany, MedicalRep, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [showPasswords, setShowPasswords] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    try {
      const [h, c, m, a, p] = await Promise.all([
        storageService.getHospitals(),
        storageService.getCompanies(),
        storageService.getMRs(),
        storageService.getApplications(),
        storageService.getPasses()
      ]);

      setHospitals(h);
      setCompanies(c);
      setMrs(m);
      setApps(a);
      setPasses(p);
    } catch (err) {
      console.error("Refresh failed", err);
    }
  };

  const handleSaveHospital = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    setIsSaving(true);
    const hospitalId = editingHospital.id || crypto.randomUUID();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      address: editingHospital.address || '',
      email: editingHospital.email || '',
      mobile_number: editingHospital.mobile_number || '',
      is_active: editingHospital.is_active ?? true,
      supported_sessions: editingHospital.supported_sessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      pass_limits: editingHospital.pass_limits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      session_windows: editingHospital.session_windows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    try {
      // 1. Save Hospital record
      const { error: hospitalError } = await supabase.from('hospitals').upsert(hospitalData);
      if (hospitalError) throw hospitalError;

      // 2. Fetch existing profiles for this hospital to find matching roles for update
      const { data: existingProfiles } = await supabase
        .from('profiles')
        .select('id, role')
        .eq('hospital_id', hospitalId);

      const existingAdmin = existingProfiles?.find(p => p.role === 'HOSPITAL_ADMIN');
      const existingSecurity = existingProfiles?.find(p => p.role === 'SECURITY');

      // 3. Prepare Staff Profile Accounts (Managed Sub-accounts)
      const profilesToUpsert = [
        { 
          id: existingAdmin?.id || crypto.randomUUID(), 
          hospital_id: hospitalId, 
          role: 'HOSPITAL_ADMIN', 
          full_name: adminData.fullName, 
          mobile_number: adminData.mobileNumber, 
          password: adminData.password 
        },
        { 
          id: existingSecurity?.id || crypto.randomUUID(), 
          hospital_id: hospitalId, 
          role: 'SECURITY', 
          full_name: securityData.fullName, 
          mobile_number: securityData.mobileNumber, 
          password: securityData.password 
        }
      ];

      // 4. Upsert to public.profiles table
      const { error: upsertError } = await supabase.from('profiles').upsert(profilesToUpsert);
      if (upsertError) throw upsertError;

      await refreshData();
      setIsHospitalModalOpen(false);
      setEditingHospital(null);
      setAdminData({ fullName: '', mobileNumber: '', password: '' });
      setSecurityData({ fullName: '', mobileNumber: '', password: '' });
      showFeedback(editingHospital.id ? "Facility updated." : "Facility Provisioned!");
    } catch (err: any) {
      console.error("Save Error:", err);
      showFeedback(err.message || "Failed to save data. Check SQL configuration.", "error");
    } finally {
      setIsSaving(false);
    }
  };

  const startEditHospital = async (h: Hospital) => {
    setEditingHospital(h);
    try {
      const { data: users, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('hospital_id', h.id);

      if (error) throw error;

      const admin = users?.find(u => u.role === 'HOSPITAL_ADMIN');
      const security = users?.find(u => u.role === 'SECURITY');

      setAdminData({ 
        fullName: admin?.full_name || '', 
        mobileNumber: admin?.mobile_number || '', 
        password: admin?.password || '' 
      });
      setSecurityData({ 
        fullName: security?.full_name || '', 
        mobileNumber: security?.mobile_number || '', 
        password: security?.password || '' 
      });
      setIsHospitalModalOpen(true);
    } catch (err) {
      showFeedback("Failed to load staff profiles.", "error");
    }
  };

  const handleSaveCompany = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.company_code) return;

    try {
      const companyData = {
        id: editingCompany.id || crypto.randomUUID(),
        name: editingCompany.name,
        company_code: editingCompany.company_code,
        admin_mobile: editingCompany.admin_mobile,
        admin_password: editingCompany.admin_password,
        is_active: editingCompany.is_active ?? true,
        contact_email: editingCompany.contact_email
      };
      const { error } = await supabase.from('pharma_companies').upsert(companyData);
      if (error) throw error;
      await refreshData();
      setIsCompanyModalOpen(false);
      setEditingCompany(null);
      showFeedback("Company registered.");
    } catch (err: any) {
      showFeedback(err.message || "Save failed.", "error");
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Facility Registry</h3>
            <button 
              onClick={() => { 
                setEditingHospital({ supported_sessions: ['MORNING', 'EVENING', 'FULL_DAY'], is_active: true }); 
                setAdminData({ fullName: '', mobileNumber: '', password: '' });
                setSecurityData({ fullName: '', mobileNumber: '', password: '' });
                setIsHospitalModalOpen(true); 
              }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> PROVISION HOSPITAL
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 relative group hover:shadow-md transition-all">
                <div className={`absolute top-4 right-4 w-2 h-2 rounded-full ${h.is_active ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-red-500'}`}></div>
                <h4 className="font-black text-slate-800 text-lg mb-1">{h.name}</h4>
                <p className="text-[10px] text-slate-400 font-bold flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Address Pending'}</p>
                <button 
                  onClick={() => startEditHospital(h)}
                  className="w-full py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-xs font-black hover:bg-indigo-50 hover:border-indigo-200 hover:text-indigo-600 transition-all flex items-center justify-center gap-2 shadow-sm"
                >
                  <Edit3 className="h-3.5 w-3.5" /> MANAGE ACCOUNTS
                </button>
              </div>
            ))}
            {hospitals.length === 0 && <div className="col-span-full py-20 text-center text-slate-400 italic">No hospitals provisioned.</div>}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Partnership Management</h3>
            <button 
              onClick={() => { setEditingCompany({ is_active: true }); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> NEW PARTNER
            </button>
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            {companies.map(c => (
              <div key={c.id} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl flex justify-between items-center">
                <div>
                  <h4 className="font-bold">{c.name}</h4>
                  <p className="text-[10px] uppercase font-black text-slate-400">{c.company_code}</p>
                </div>
                <button onClick={() => { setEditingCompany(c); setIsCompanyModalOpen(true); }} className="p-2 hover:bg-indigo-50 rounded-lg"><Edit3 className="h-4 w-4" /></button>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Hospital Provisioning / Edit Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">{editingHospital?.id ? 'Configure Facility' : 'Provision New Facility'}</h3>
              <button onClick={() => setIsHospitalModalOpen(false)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
              <div className="flex justify-between items-center mb-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Basic Details</label>
                <button 
                  type="button" 
                  onClick={() => setShowPasswords(!showPasswords)}
                  className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded hover:bg-indigo-100 transition-all"
                >
                  {showPasswords ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
                  {showPasswords ? 'HIDE' : 'SHOW'} PASSWORDS
                </button>
              </div>

              <div className="space-y-4">
                <input required type="text" value={editingHospital?.name || ''} onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Hospital Name" />
                <textarea value={editingHospital?.address || ''} onChange={e => setEditingHospital({...editingHospital, address: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-20" placeholder="Address" />
              </div>

              <div className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 space-y-4">
                <div className="flex items-center justify-between">
                  <p className="text-xs font-black text-indigo-900 uppercase">Management Node (Admin)</p>
                  <ShieldCheck className="h-4 w-4 text-indigo-400" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <input required type="text" value={adminData.fullName} onChange={e => setAdminData({...adminData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Admin Full Name" />
                  <input required type="text" value={adminData.mobileNumber} onChange={e => setAdminData({...adminData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Admin Login ID" />
                  <input required type={showPasswords ? "text" : "password"} value={adminData.password} onChange={e => setAdminData({...adminData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold col-span-2" placeholder="Password" />
                </div>
              </div>

              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                <div className="flex items-center justify-between">
                  <p className="text-xs font-black text-slate-800 uppercase">Verification Post (Security)</p>
                  <Lock className="h-4 w-4 text-slate-400" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <input required type="text" value={securityData.fullName} onChange={e => setSecurityData({...securityData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Guard Full Name" />
                  <input required type="text" value={securityData.mobileNumber} onChange={e => setSecurityData({...securityData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Guard Login ID" />
                  <input required type={showPasswords ? "text" : "password"} value={securityData.password} onChange={e => setSecurityData({...securityData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold col-span-2" placeholder="Password" />
                </div>
              </div>

              <button type="submit" disabled={isSaving} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all uppercase tracking-widest text-sm">
                {isSaving ? 'SYNCHRONIZING...' : 'COMMIT CHANGES'}
              </button>
            </form>
          </div>
        </div>
      )}

      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">Pharma Partner</h3>
              <button onClick={() => setIsCompanyModalOpen(false)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-8 space-y-4">
              <input required type="text" value={editingCompany?.name || ''} onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" placeholder="Company Name" />
              <input required type="text" value={editingCompany?.company_code || ''} onChange={e => setEditingCompany({...editingCompany, company_code: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl font-bold text-indigo-700" placeholder="Unique Code" />
              <div className="grid grid-cols-2 gap-3">
                <input required type="text" value={editingCompany?.admin_mobile || ''} onChange={e => setEditingCompany({...editingCompany, admin_mobile: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold" placeholder="Login ID" />
                <input required type="password" value={editingCompany?.admin_password || ''} onChange={e => setEditingCompany({...editingCompany, admin_password: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold" placeholder="Password" />
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl">SAVE PARTNER</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService, supabase } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight, Zap } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = async (e?: React.FormEvent) => {
    e?.preventDefault();
    setIsAuthenticating(true);

    try {
      if (role === 'MR') {
        const mrs = await storageService.getMRs();
        const existing = mrs.find(m => m.login_id === mobile || m.full_name === mobile);
        if (existing) {
          if (existing.status === 'suspended') {
            showFeedback("Account suspended.", 'error');
          } else if (existing.password === password) {
            const u: AuthUser = { 
              id: existing.id, 
              fullName: existing.full_name, 
              role: 'MR', 
              companyName: existing.company_name, 
              loginId: existing.login_id,
              mobileNumber: existing.mobile_number 
            };
            storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
            showFeedback(`Welcome, ${u.fullName}!`);
          } else {
            showFeedback("Invalid credentials.", 'error');
          }
        } else {
          showFeedback("MR not found.", 'error');
        }
      } else if (role === 'COMPANY') {
        const companies = await storageService.getCompanies();
        const found = companies.find(c => c.admin_mobile === mobile || c.name === mobile);
        if (found && found.admin_password === password) {
          if (!found.is_active) {
            showFeedback("Deactivated.", 'error');
          } else {
            const u: AuthUser = { 
              id: found.id, 
              role: 'COMPANY', 
              fullName: `${found.name} Admin`,
              companyId: found.id 
            };
            storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
            showFeedback(`Partner Access: ${found.name}`);
          }
        } else {
          showFeedback("Invalid credentials.", 'error');
        }
      } else if (role === 'HOSPITAL_ADMIN' || role === 'SECURITY' || role === 'SUPER_ADMIN') {
        // Emergency root bypass
        if (role === 'SUPER_ADMIN' && mobile === 'root' && password === 'root') {
          const u: AuthUser = { id: 'sa-root', role: 'SUPER_ADMIN', fullName: 'System Root' };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback("Emergency root session.");
          return;
        }

        // Search profiles by role
        const { data: profiles, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('role', role);

        if (error) throw error;

        // Find match by mobile number OR full name
        const found = profiles?.find(p => 
          (p.mobile_number && p.mobile_number === mobile) || 
          (p.full_name && p.full_name === mobile)
        );

        if (found && found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role as UserRole, 
            fullName: found.full_name, 
            hospitalId: found.hospital_id,
            mobileNumber: found.mobile_number
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Welcome, ${found.full_name}`);
        } else {
          showFeedback("Access Denied: Check identity and password.", 'error');
        }
      }
    } catch (err: any) {
      console.error("Auth Failure:", err);
      showFeedback(err.message || "Connection error. Please try again.", "error");
    } finally {
      setIsAuthenticating(false);
    }
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY', 'HOSPITAL_ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => { setRole(r); setMobile(''); setPassword(''); }} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form id="loginForm" onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Login ID / Identity</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'SUPER_ADMIN' ? "Identity" : "Admin ID / Mobile"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button 
                  type="submit" 
                  disabled={isAuthenticating}
                  className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  {isAuthenticating ? 'Authenticating...' : 'Enter System'} <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user!} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user?.role === 'SUPER_ADMIN' ? 'Root Authority' : user?.role === 'MR' ? 'MR Dashboard' : `${user?.fullName} Panel`}
      >
        {user?.role === 'MR' && <MRDashboard user={user as any} />}
        {user?.role === 'COMPANY' && <CompanyAdminDashboard user={user} />}
        {user?.role === 'HOSPITAL_ADMIN' && <AdminDashboard user={user as any} />}
        {user?.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user?.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

