import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar, ChevronRight, ExternalLink
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'settings'>('lottery');
  const [brief, setBrief] = useState('');

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    try {
      const allHospitals = await storageService.getHospitals();
      const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

      const [allMRs, allCompanies, allApps, allPasses, allLogs, allApprovals] = await Promise.all([
        storageService.getMRs(),
        storageService.getCompanies(),
        storageService.getApplications(),
        storageService.getPasses(),
        storageService.getLogs(),
        storageService.getApprovals()
      ]);

      setHospitals(allHospitals);
      setMrs(allMRs); 
      setCompanies(allCompanies);
      setApps(allApps); 
      setPasses(allPasses);
      setLogs(allLogs);
      setApprovals(allApprovals);

      if (currentHosp && !editingHospital) {
        setEditingHospital(currentHosp);
      }

      const summary = await getAdminBriefing(allApps, allPasses, currentHosp?.name || 'Hospital');
      setBrief(summary);
    } catch (e) {
      console.error("Refresh failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
  }, [refreshData]);

  const handleManualLottery = async (session: SessionType) => {
    const result = await lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      await refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = async () => {
    if (!editingHospital) return;
    try {
      await storageService.saveHospitals([editingHospital]);
      showFeedback("System settings saved successfully.", "success");
      await refreshData();
    } catch (err) {
      showFeedback("Failed to save settings.", "error");
    }
  };

  const handleUpdateApproval = async (id: string, status: 'approved' | 'rejected') => {
    try {
      const allApprovals = await storageService.getApprovals();
      const updated = allApprovals.map(a => a.id === id ? { ...a, status, updated_at: new Date().toISOString() } : a);
      await storageService.saveApprovals(updated);
      await refreshData();
      showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
    } catch (err) {
      showFeedback("Update failed.", "error");
    }
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return <div className="p-20 text-center text-slate-400">Loading Facility...</div>;

  const pendingApprovals = approvals.filter(a => a.hospital_id === user.hospitalId && a.status === 'pending');

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium">{brief || "Analyzing patterns..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          Requests {pendingApprovals.length > 0 && <span className="bg-red-500 text-white text-[8px] px-1 rounded-full">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
             if (!currentHospital.supported_sessions.includes(sess)) return null;
             const today = new Date().toISOString().split('T')[0];
             const count = apps.filter(a => a.hospital_id === user.hospitalId && a.application_date === today && a.session === sess && a.status === 'applied').length;
             return (
               <div key={sess} className="p-6 bg-white border border-slate-100 rounded-3xl shadow-sm">
                 <h4 className="font-black text-slate-800 mb-4">{sess}</h4>
                 <div className="flex items-center justify-between mb-6">
                    <p className="text-xs text-slate-400">Applications Today: {count}</p>
                 </div>
                 <button 
                   disabled={count === 0}
                   onClick={() => handleManualLottery(sess)}
                   className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl hover:bg-indigo-700 disabled:opacity-50"
                 >
                   MANUAL SPIN NOW
                 </button>
               </div>
             );
          })}
        </div>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
           <h3 className="text-xl font-bold mb-6">Pending Access Requests</h3>
           <div className="space-y-4">
              {pendingApprovals.map(a => {
                const mr = mrs.find(m => m.id === a.mr_id);
                return (
                  <div key={a.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                     <div className="flex items-center gap-3">
                        <User className="h-5 w-5 text-slate-400" />
                        <div>
                           <p className="font-bold">{mr?.full_name || 'Loading...'}</p>
                           <p className="text-[10px] uppercase font-black text-indigo-600">{mr?.company_name}</p>
                        </div>
                     </div>
                     <div className="flex gap-2">
                        <button onClick={() => handleUpdateApproval(a.id, 'rejected')} className="px-4 py-2 bg-white border border-red-100 text-red-500 text-xs font-bold rounded-xl hover:bg-red-50">Reject</button>
                        <button onClick={() => handleUpdateApproval(a.id, 'approved')} className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700">Approve</button>
                     </div>
                  </div>
                );
              })}
              {pendingApprovals.length === 0 && <p className="text-center py-10 text-slate-400">No pending requests.</p>}
           </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-xl mx-auto">
           <h3 className="text-xl font-bold mb-8">Facility Settings</h3>
           <div className="space-y-6">
              <div>
                 <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Hospital Name</label>
                 <input type="text" readOnly value={editingHospital.name} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500" />
              </div>
              <div>
                 <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Address</label>
                 <textarea value={editingHospital.address || ''} onChange={e => setEditingHospital({...editingHospital, address: e.target.value})} className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold h-24" />
              </div>
              <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl">Save Changes</button>
           </div>
        </section>
      )}
    </div>
  );
};

export default AdminDashboard;

import { GoogleGenAI } from "@google/genai";
import { PassApplication, IssuedPass } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getPriorityInsights = async (history: { date: string, status: string }[], userName: string) => {
  try {
    const model = 'gemini-3-flash-preview';
    const prompt = `
      Context: A Medical Representative (MR) named ${userName} is using a hospital pass booking system.
      System Rules:
      - 14 days without a pass: +5 priority points.
      - 7 days without a pass: +3 priority points.
      - Pass in last 3 days: -5 priority points (Cool-down period).
      - Missed entry (no-show): -10 points.

      User Recent History: ${JSON.stringify(history)}

      Task: Write a 2-sentence encouraging insight for ${userName}. 
      Explain their current standing and give one tip to improve their chances in the next lottery.
      Tone: Professional, supportive, and clear.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text || "Your priority standing is calculated based on visit frequency. Regular applications help improve your score.";
  } catch (error) {
    console.error("AI Insight retrieval failed", error);
    return "Your priority standing is calculated based on visit frequency. Regular applications help improve your score.";
  }
};

export const getAdminBriefing = async (apps: PassApplication[], passes: IssuedPass[], hospitalName: string) => {
  try {
    const model = 'gemini-3-flash-preview';
    const today = new Date().toISOString().split('T')[0];

    // Only analyze today's relevant data for this specific briefing
    const todayApps = apps.filter(a => a.application_date === today);
    const todayPasses = passes.filter(p => p.pass_date === today);

    const prompt = `
      Context: You are an AI analyst for ${hospitalName}. 
      Today's Data Summary: 
      - Total Applications: ${todayApps.length}
      - Passes Issued: ${todayPasses.length}
      - Success Rate: ${todayApps.length > 0 ? ((todayPasses.length / todayApps.length) * 100).toFixed(1) : 0}%

      Task: Provide a one-sentence high-level summary of today's demand and a specific recommendation for tomorrow's pass limits to optimize traffic flow.
      Tone: Analytical and concise.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text || "System usage is stable. Monitor application counts to adjust daily pass capacities if needed.";
  } catch (error) {
    console.error("AI Briefing retrieval failed", error);
    return "System usage is stable. Monitor application counts to adjust daily pass capacities if needed.";
  }
};

import { storageService, supabase } from './storageService';
import { SessionType, PassApplication, IssuedPass } from '../types';

export const lotteryService = {
  // Priority calculation shell - usually handled by data in the DB
  calculatePriority: async (mrId: string): Promise<number> => {
    return 0; 
  },

  runLottery: async (hospitalId: string, session: SessionType): Promise<{ success: boolean; count: number; message: string }> => {
    try {
      // 1. Fetch Hospital Settings
      const allHospitals = await storageService.getHospitals();
      const hospital = allHospitals.find(h => h.id === hospitalId);
      if (!hospital) throw new Error('Hospital not found');

      const today = new Date().toISOString().split('T')[0];

      // 2. Check if already run for this session today
      const allPasses = await storageService.getPasses();
      const existing = allPasses.filter(p => 
        p.hospital_id === hospitalId && 
        p.session === session && 
        p.pass_date === today
      );

      if (existing.length > 0) {
        return {
          success: false,
          count: 0,
          message: "Lottery already run for this session today."
        };
      }

      // 3. Get Applications for the current session/today
      const allApps = await storageService.getApplications();
      const targetApps = allApps.filter(a => 
        a.hospital_id === hospitalId && 
        a.session === session && 
        a.application_date === today && 
        a.status === 'applied'
      );

      if (targetApps.length === 0) {
        return { 
          success: true, 
          count: 0, 
          message: 'No pending applications found for this session today.' 
        };
      }

      // 4. Scoring and Selection
      // Sort by priority_score descending
      const scored = targetApps.sort((a, b) => (b.priority_score || 0) - (a.priority_score || 0));
      const limit = (hospital.pass_limits as any)[session] || 0;

      const selected = scored.slice(0, limit);
      const waitlisted = scored.slice(limit);

      // 5. Generate Passes
      const newPasses: IssuedPass[] = selected.map((s, idx) => ({
        id: crypto.randomUUID(),
        mr_id: s.mr_id,
        hospital_id: hospitalId,
        session: session,
        pass_date: today,
        time_slot: ["09:00 - 10:00", "10:00 - 11:00", "11:00 - 12:00"][idx % 3],
        qr_code: `MEDPASS-GATE-${hospitalId}`, // Reference to Gate ID
        entry_status: 'not_entered'
      }));

      // 6. Update Database
      if (newPasses.length > 0) {
        const { error: passErr } = await supabase.from('passes').insert(newPasses);
        if (passErr) throw passErr;
      }

      // Update application statuses
      for (const s of selected) {
        await supabase.from('applications').update({ status: 'selected' }).eq('id', s.id);
      }
      for (const w of waitlisted) {
        await supabase.from('applications').update({ status: 'waitlisted' }).eq('id', w.id);
      }

      return {
        success: true,
        count: selected.length,
        message: `Lottery completed: ${selected.length} representatives selected.`
      };
    } catch (error: any) {
      console.error("Lottery execution failed", error);
      return {
        success: false,
        count: 0,
        message: error.message || "Failed to execute lottery."
      };
    }
  }
};

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
